Patch.GlslSource:
#version 150
in vec3 vPixelPos3D;
in vec2 vPixelPos2D;
out vec4 fragColor;
#define iPixelPos3D vPixelPos3D
#define iPixelPos2D vPixelPos2D
uniform float time;
uniform vec2 resolution;

void main() {
    float speed = 0.5;
    float sweep = mod(time * speed, 1.0);
    float bar   = smoothstep(sweep - 0.04, sweep, iPixelPos2D.x)
                - smoothstep(sweep, sweep + 0.04, iPixelPos2D.x);
    float bg = 0.05;
    float brightness = bg + bar * (1.0 - bg);
    fragColor = vec4(brightness, brightness, brightness * 0.8, 1.0);
}

EffectBank.Effect:
#version 150
in vec3 vPixelPos3D;
in vec2 vPixelPos2D;
out vec4 fragColor;
#define iPixelPos3D vPixelPos3D
#define iPixelPos2D vPixelPos2D
uniform float time;
uniform vec2 resolution;

void main() {
    float x = iPixelPos2D.x * 10.0;
    float y = iPixelPos2D.y * 10.0;

    float v1 = sin(x + time);
    float v2 = sin(10.0 * (x * sin(time / 2.0) + y * cos(time / 3.0)) + time);

    float cx = x + 5.0 * sin(time / 5.0);
    float cy = y + 5.0 * cos(time / 3.0);
    float v3 = sin(sqrt(cx*cx + cy*cy + 1.0) - time);

    float v = (v1 + v2 + v3) / 3.0;

    float r = sin(v * 3.1415) * 0.5 + 0.5;
    float g = sin(v * 3.1415 + 2.094) * 0.5 + 0.5;
    float b = sin(v * 3.1415 + 4.188) * 0.5 + 0.5;

    fragColor = vec4(r, g, b, 1.0);
}

#version 150
in vec3 vPixelPos3D;
in vec2 vPixelPos2D;
out vec4 fragColor;
#define iPixelPos3D vPixelPos3D
#define iPixelPos2D vPixelPos2D
uniform float time;
uniform vec2 resolution;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
    vec2 i = floor(p); vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i+vec2(1,0)), u.x),
               mix(hash(i+vec2(0,1)), hash(i+vec2(1,1)), u.x), u.y);
}
void main() {
    vec2 q = iPixelPos2D;
    q.y = 1.0 - q.y;  // flame rises upward
    float t = time * 1.5;
    float f = noise(q * vec2(10.0, 5.0) + vec2(0.0, -t));
    f += 0.5 * noise(q * vec2(10.0, 10.0) + vec2(0.0, -t * 1.3));
    f = clamp(f - q.y * 1.1, 0.0, 1.0);
    vec3 fire = mix(vec3(1.0, 0.0, 0.0), vec3(1.0, 0.9, 0.0), f);
    fire = mix(vec3(0.0), fire, pow(f, 0.4));
    fragColor = vec4(fire, 1.0);
}

