#version 150
in vec3 vPixelPos3D;
in vec2 vPixelPos2D;
out vec4 fragColor;
#define iPixelPos3D vPixelPos3D
#define iPixelPos2D vPixelPos2D
uniform float time;
uniform vec2 resolution;

// Protean clouds by nimitz (twitter: @stormoid)
// https://www.shadertoy.com/view/3l23Rh
// License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License

mat2 rot(in float a){float c = cos(a), s = sin(a);return mat2(c,s,-s,c);}
const mat3 m3 = mat3(0.33338, 0.56034, -0.71817, -0.87887, 0.32651, -0.15323, 0.15162, 0.69596, 0.61339)*1.93;

float mag2(vec2 p){return dot(p,p);}
float linstep(in float mn, in float mx, in float x){ return clamp((x - mn)/(mx - mn), 0., 1.); }

float prm1 = 0.;
vec2 bsMo = vec2(0.0);

vec2 disp(float t){ return vec2(sin(t*0.22)*1., cos(t*0.175)*1.)*2.; }

vec2 map(vec3 p)
{
    vec3 p2 = p;
    p2.xy -= disp(p.z).xy;
    p.xy *= rot(sin(p.z+time)*(0.1 + prm1*0.05) + time*0.09);
    float cl = mag2(p2.xy);
    float d = 0.;
    p *= .61;
    float z = 1.;
    float trk = 1.;
    float dspAmp = 0.1 + prm1*0.2;
    for(int i = 0; i < 5; i++)
    {
        p += sin(p.zxy*0.75*trk + time*trk*.8)*dspAmp;
        d -= abs(dot(cos(p), sin(p.yzx))*z);
        z *= 0.57;
        trk *= 1.4;
        p = p*m3;
    }
    d = abs(d + prm1*3.)+ prm1*.3 - 2.5 + bsMo.y;
    return vec2(d + cl*.2 + 0.25, cl);
}

vec4 render( in vec3 ro, in vec3 rd, float t_val )
{
    vec4 rez = vec4(0);
    const float ldst = 8.;
    vec3 lpos = vec3(disp(t_val + ldst)*0.5, t_val + ldst);
    float t = 1.5;
    float fogT = 0.;
    for(int i=0; i<130; i++)
    {
        if(rez.a > 0.99)break;

        vec3 pos = ro + t*rd;
        vec2 mpv = map(pos);
        float den = clamp(mpv.x-0.3,0.,1.)*1.12;
        float dn = clamp((mpv.x + 2.),0.,3.);

        vec4 col = vec4(0);
        if (mpv.x > 0.6)
        {
            col = vec4(sin(vec3(5.,0.4,0.2) + mpv.y*0.1 +sin(pos.z*0.4)*0.5 + 1.8)*0.5 + 0.5,0.08);
            col *= den*den*den;
            col.rgb *= linstep(4.,-2.5, mpv.x)*2.3;
            float dif =  clamp((den - map(pos+.8).x)/9., 0.001, 1. );
            dif += clamp((den - map(pos+.35).x)/2.5, 0.001, 1. );
            col.xyz *= den*(vec3(0.005,.045,.075) + 1.5*vec3(0.033,0.07,0.03)*dif);
        }

        float fogC = exp(t*0.2 - 2.2);
        col.rgba += vec4(0.06,0.11,0.11, 0.1)*clamp(fogC-fogT, 0., 1.);
        fogT = fogC;
        rez = rez + col*(1. - rez.a);
        t += clamp(0.5 - dn*dn*.05, 0.09, 0.3);
    }
    return clamp(rez, 0.0, 1.0);
}

float getsat(vec3 c)
{
    float mi = min(min(c.x, c.y), c.z);
    float ma = max(max(c.x, c.y), c.z);
    return (ma - mi)/(ma+ 1e-7);
}

vec3 iLerp(in vec3 a, in vec3 b, in float x)
{
    vec3 ic = mix(a, b, x) + vec3(1e-6,0.,0.);
    float sd = abs(getsat(ic) - mix(getsat(a), getsat(b), x));
    vec3 dir = normalize(vec3(2.*ic.x - ic.y - ic.z, 2.*ic.y - ic.x - ic.z, 2.*ic.z - ic.y - ic.x));
    float lgt = dot(vec3(1.0), ic);
    float ff = dot(dir, normalize(ic));
    ic += 1.5*dir*sd*ff*lgt;
    return clamp(ic,0.,1.);
}

void main() 
{   
    // Using your 'iPixelPos2D' input instead of calculating from gl_FragCoord
    vec2 q = iPixelPos2D;
    vec2 p = (iPixelPos2D - 0.5) * (resolution.xy / resolution.y);

    // Fallback for iMouse
    bsMo = vec2(0.0);

    float t_val = time*3.;
    vec3 ro = vec3(0,0,t_val);

    ro += vec3(sin(time)*0.5,sin(time*1.)*0.,0);

    float dspAmp = .85;
    ro.xy += disp(ro.z)*dspAmp;
    float tgtDst = 3.5;

    vec3 target = normalize(ro - vec3(disp(t_val + tgtDst)*dspAmp, t_val + tgtDst));
    ro.x -= bsMo.x*2.;
    vec3 rightdir = normalize(cross(target, vec3(0,1,0)));
    vec3 updir = normalize(cross(rightdir, target));
    rightdir = normalize(cross(updir, target));
    vec3 rd=normalize((p.x*rightdir + p.y*updir)*1. - target);
    rd.xy *= rot(-disp(t_val + 3.5).x*0.2 + bsMo.x);
    prm1 = smoothstep(-0.4, 0.4,sin(time*0.3));

    vec4 scn = render(ro, rd, t_val);

    vec3 col = scn.rgb;
    col = iLerp(col.bgr, col.rgb, clamp(1.-prm1,0.05,1.));

    col = pow(col, vec3(.55,0.65,0.6))*vec3(1.,.97,.9);

    // Vignette
    col *= pow( 16.0*q.x*q.y*(1.0-q.x)*(1.0-q.y), 0.12)*0.7+0.3; 

    fragColor = vec4( col, 1.0 );
}

#version 150
in vec3 vPixelPos3D;
in vec2 vPixelPos2D;
out vec4 fragColor;
#define iPixelPos3D vPixelPos3D
#define iPixelPos2D vPixelPos2D
uniform float time;
uniform vec2 resolution;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
void main() {
    vec2 cell = floor(iPixelPos2D * 20.0);
    float rnd  = hash(cell + floor(time * 12.0));
    float spark = step(0.94, rnd);
    fragColor = vec4(vec3(spark), 1.0);
}

#version 150
in vec3 vPixelPos3D;
in vec2 vPixelPos2D;
out vec4 fragColor;
#define iPixelPos3D vPixelPos3D
#define iPixelPos2D vPixelPos2D
uniform float time;
uniform vec2 resolution;

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
void main() {
    float hue = mod(time * 0.05, 1.0);
    vec3 col = hsv2rgb(vec3(hue, 0.9, 1.0));
    fragColor = vec4(col, 1.0);
}

#version 150
in vec3 vPixelPos3D;
in vec2 vPixelPos2D;
out vec4 fragColor;
#define iPixelPos3D vPixelPos3D
#define iPixelPos2D vPixelPos2D
uniform float time;
uniform vec2 resolution;
uniform vec3 pixelPosMin;
uniform vec3 pixelPosMax;

void main() {
    vec3 dir = normalize(vec3(1.0, 0.4, 0.7));
    float proj = dot(iPixelPos3D, dir);

    float spatialFreq = 0.01;
    float speed = 6.0;
    float wave = sin(proj * spatialFreq - time * speed) * 0.5 + 0.5;

    vec3 col = vec3(0.5 + 0.5 * sin(proj * 0.003 + time),
                    0.5 + 0.5 * sin(proj * 0.003 + time + 2.09),
                    0.5 + 0.5 * sin(proj * 0.003 + time + 4.18));
    fragColor = vec4(col * wave, 1.0);
}

#define PI 3.14159265

vec3 palette(in float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.1, 0.4, 0.5);
    return a + b * cos(2.0 * PI * (c * t + d));
}

vec4 wave(vec2 uv, vec4 color, float amp, float freq, float phase, float thick, vec3 hue) {
    float x = uv.x - phase;
    float y = uv.y + amp * sin(freq * x);
    float bright = smoothstep(0.0, 1.0, 1.0 - abs(y) / thick);
    return vec4(vec3(bright) * hue, 1.0);
}

void mainImage(out vec4 color, in vec2 coord) {
    vec2 uv = (2.0 * coord - iResolution.xy) / iResolution.y;

    color = vec4(0.0, 0.0, 0.0, 1.0);

    for (float layer = 0.0; layer < 1.0; layer += 0.1) {
        float amp = 0.25 + 0.25 * sin(iTime + layer) * (1.0 - layer);
        float freq = 2.0;
        float phase = iTime * (1.0 - layer);
        float thick = 0.01 + 0.001 * pow(abs(uv.x), 8.0);
        vec3 hue = palette(0.5 * uv.x + 1.0 * layer - 0.5 * iTime);
        color += wave(uv, color, amp, freq, phase, thick, hue);
    }
}

vec2 fromPolar(float r,float a){
    return r*vec2(cos(a),sin(a));
}

float rand(vec2 st){
    return fract(sin(dot(st,vec2(13.2,62.232)))*2384.23)*2.-1.;
}

vec2 getPoint(vec2 i_st){
    return fract(vec2(rand(i_st),rand(i_st+10.)));
}

float noise(vec2 st){
    vec2 i=floor(st);
    vec2 f=fract(st);
    vec2 u=f*f*f*(f*(6.*f-15.)+10.);
    float a=rand(i+vec2(0.,0.));
    float b=rand(i+vec2(1.,0.));
    float c=rand(i+vec2(0.,1.));
    float d=rand(i+vec2(1.,1.));
    return mix(
        mix(a,b,u.x),
        mix(c,d,u.x),
        u.y
    );
}

vec2 getPoint2(vec2 i_st){
    float r=(noise(100.*i_st + + iTime / 5.)+1.)/2.;// [0, 0.5]
    float angle=3.1415*(noise(32.13*i_st + iTime / 5.));
    vec2 coords=fromPolar(r,angle);
    coords=coords*.5+.5;
    return coords;
}
void mainImage(out vec4 fragColor, in vec2 fragCoord){

    float grid=12.;
    vec2 st=fragCoord.xy/iResolution.xy;
    float aspect=iResolution.x/iResolution.y;
    st.x*=aspect;

    float m_dist=distance(st , iMouse.xy / iResolution.xy * vec2(aspect,1.))*grid;
    float m_dist2=1000.;

    vec3 ORANGE = vec3(1.,.5,.25);
    vec3 color=ORANGE;
    vec3 color2=ORANGE;

    vec2 i_st=floor(st*grid);
    vec2 f_st=fract(st*grid);
    vec2 point_=getPoint2(i_st);
    for(int i=0;i<9;i++){
        vec2 d=vec2(mod(float(i),3.)-1.,float(i/3-1));
        float dist=distance(f_st,(d+getPoint2(i_st+d))
        );
        if(dist<=m_dist){
            m_dist2=m_dist;
            m_dist=dist;
            color2=color;
            color=vec3((rand(i_st+d)+1.)/2.);
        }else if(dist<=m_dist2){
            m_dist2=dist;
            color2=vec3((rand(i_st+d)+1.)/2.);
        }
    }
    color = color * step(0.5,fract(6. * (m_dist2 - m_dist + iTime/10.)));
    fragColor=vec4(color,1.);
}

#ifdef GL_ES
precision mediump float;
#endif

float cosRange(float amt, float range, float minimum) {
	return (((1.0 + cos(radians(amt))) * 0.5) * range) + minimum;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    const int zoom = 40;
    const float brightness = 0.975;
	float time = iTime * 1.25;
	vec2 uv = fragCoord.xy / iResolution.xy;
	vec2 p  = (2.0*fragCoord.xy-iResolution.xy)/max(iResolution.x,iResolution.y);
	float ct = cosRange(time*5.0, 3.0, 1.1);
	float xBoost = cosRange(time*0.2, 5.0, 5.0);
	float yBoost = cosRange(time*0.1, 10.0, 5.0);
	float fScale = cosRange(time * 15.5, 1.25, 0.5);

	for(int i=1;i<zoom;i++) {
		float _i = float(i);
		vec2 newp=p;
		newp.x+=0.25/_i*sin(_i*p.y+time*cos(ct)*0.5/20.0+0.005*_i)*fScale+xBoost;		
		newp.y+=0.25/_i*sin(_i*p.x+time*ct*0.3/40.0+0.03*float(i+15))*fScale+yBoost;
		p=newp;
	}

	vec3 col=vec3(0.5*sin(3.0*p.x)+0.5,0.5*sin(3.0*p.y)+0.5,sin(p.x+p.y));
	col *= brightness;

    // Add border
    float vigAmt = 5.0;
    float vignette = (1.-vigAmt*(uv.y-.5)*(uv.y-.5))*(1.-vigAmt*(uv.x-.5)*(uv.x-.5));
	float extrusion = (col.x + col.y + col.z) / 4.0;
    extrusion *= 1.5;
    extrusion *= vignette;

	fragColor = vec4(col, extrusion);
}

